BEGIN;
ALTER TABLE "FinanceMovement" ADD COLUMN "feeAmount" NUMERIC(20,2) NOT NULL DEFAULT 0 CHECK("feeAmount">=0);
ALTER TABLE "FinanceMovement" DROP CONSTRAINT "FinanceMovement_amount_check";
ALTER TABLE "FinanceMovement" ADD CONSTRAINT "FinanceMovement_amount_check" CHECK(amount>=0 AND(amount>0 OR kind IN('INVESTMENT_DISPOSAL','REVERSAL'))),ADD CONSTRAINT "FinanceMovement_fee_shape" CHECK("feeAmount"=0 OR kind IN('INVESTMENT_DISPOSAL','REVERSAL'));
ALTER TABLE "FinanceInvestmentEvent" ADD COLUMN "recordedAt" TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),ALTER COLUMN "journalId" DROP NOT NULL;
CREATE TABLE "FinanceInvestmentAllocation"(id UUID PRIMARY KEY,"movementId" UUID NOT NULL REFERENCES "FinanceMovement" ON DELETE RESTRICT,"lotId" UUID NOT NULL REFERENCES "FinanceInvestmentLot" ON DELETE RESTRICT,sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 100),"requestedUnits" NUMERIC(20,6),"requestedCarrying" NUMERIC(20,2),"disposeAll" BOOLEAN NOT NULL DEFAULT false,"costBasis" NUMERIC(20,2) NOT NULL CHECK("costBasis">=0),"carryingBasis" NUMERIC(20,2) NOT NULL CHECK("carryingBasis">=0),"unitBasis" NUMERIC(20,6),"basisCapturedAt" TIMESTAMPTZ NOT NULL,"balanceDigest" TEXT NOT NULL CHECK("balanceDigest"~'^[0-9a-f]{64}$'),UNIQUE("movementId","lotId"),UNIQUE("movementId",sequence),CHECK("costBasis">0 OR "carryingBasis">0 OR coalesce("unitBasis",0)>0));
CREATE TABLE "FinanceInvestmentIncomeEvent"(id UUID PRIMARY KEY,"holdingId" UUID NOT NULL REFERENCES "FinanceInvestmentHolding" ON DELETE RESTRICT,"movementId" UUID NOT NULL UNIQUE REFERENCES "FinanceMovement" ON DELETE RESTRICT,"journalId" UUID NOT NULL UNIQUE REFERENCES "FinanceJournalEntry" ON DELETE RESTRICT,"effectiveDate" DATE NOT NULL,amount NUMERIC(20,2) NOT NULL CHECK(amount<>0));
CREATE INDEX "FinanceInvestmentIncomeEvent_holdingId_effectiveDate_idx" ON "FinanceInvestmentIncomeEvent"("holdingId","effectiveDate");
CREATE TRIGGER "FinanceInvestmentIncomeEvent_immutable" BEFORE UPDATE OR DELETE ON "FinanceInvestmentIncomeEvent" FOR EACH ROW EXECUTE FUNCTION encova_finance_audit_immutable();
CREATE FUNCTION encova_finance_investment_lot_digest(target UUID,cutoff TIMESTAMPTZ) RETURNS TEXT LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.id),'[]'::jsonb)::text,'UTF8')),'hex') FROM public."FinanceInvestmentEvent" e WHERE e."lotId"=target AND e."recordedAt"<=cutoff $$;
CREATE FUNCTION encova_finance_investment_allocation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD."movementId" ELSE NEW."movementId" END;
 IF d.state<>'DRAFT' OR TG_OP='UPDATE' THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_IMMUTABLE' USING ERRCODE='P0001';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 IF d.kind NOT IN('INVESTMENT_DISPOSAL','INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN') OR NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentLot" WHERE id=NEW."lotId" AND "holdingId"=d."holdingId" AND "acquisitionDate"<=d."postingDate") OR NEW."basisCapturedAt">clock_timestamp() THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;RETURN NEW;
END $$;
CREATE TRIGGER "FinanceInvestmentAllocation_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceInvestmentAllocation" FOR EACH ROW EXECUTE FUNCTION encova_finance_investment_allocation_guard();
CREATE FUNCTION encova_finance_investment_set_allocations(target UUID,items JSONB) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE d public."FinanceMovement"%ROWTYPE;h public."FinanceInvestmentHolding"%ROWTYPE;l public."FinanceInvestmentLot"%ROWTYPE;x JSONB;n INTEGER:=0;cost_remaining NUMERIC;carrying_remaining NUMERIC;units_remaining NUMERIC;cost_basis NUMERIC;carrying_basis NUMERIC;unit_basis NUMERIC;requested_units NUMERIC;requested_carrying NUMERIC;all_units BOOLEAN;captured TIMESTAMPTZ;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=target FOR UPDATE;SELECT * INTO h FROM public."FinanceInvestmentHolding" WHERE id=d."holdingId" FOR UPDATE;
 IF d.state<>'DRAFT' OR jsonb_typeof(items) IS DISTINCT FROM 'array' OR jsonb_array_length(items)>100 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF d.kind NOT IN('INVESTMENT_DISPOSAL','INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN') THEN IF items<>'[]'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;RETURN;END IF;
 IF jsonb_array_length(items)<1 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 DELETE FROM public."FinanceInvestmentAllocation" WHERE "movementId"=target;
 FOR x IN SELECT * FROM jsonb_array_elements(items) LOOP
  n:=n+1;cost_basis:=0;carrying_basis:=0;unit_basis:=NULL;requested_units:=NULL;requested_carrying:=NULL;
  IF jsonb_typeof(x) IS DISTINCT FROM 'object' OR x-ARRAY['lotId','units','carryingAmount','disposeAll']<>'{}'::jsonb OR jsonb_typeof(x->'disposeAll') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO l FROM public."FinanceInvestmentLot" WHERE id=(x->>'lotId')::uuid FOR UPDATE;
  IF l.id IS NULL OR l."holdingId" IS DISTINCT FROM d."holdingId" OR l."acquisitionDate">d."postingDate" THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;
  IF EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "lotId"=l.id AND "effectiveDate">d."postingDate") THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_DATE_ORDER' USING ERRCODE='P0001';END IF;
  captured:=clock_timestamp();SELECT coalesce(sum("costDelta"),0),coalesce(sum("carryingDelta"),0),coalesce(sum("unitsDelta"),0) INTO cost_remaining,carrying_remaining,units_remaining FROM public."FinanceInvestmentEvent" WHERE "lotId"=l.id AND "effectiveDate"<=d."postingDate";
  all_units:=(x->>'disposeAll')::boolean;
  IF x->>'units' IS NOT NULL THEN IF jsonb_typeof(x->'units')<>'string' OR x->>'units' !~ '^(0|[1-9][0-9]{0,13})([.][0-9]{1,6})?$' OR(x->>'units')::numeric<=0 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;requested_units:=(x->>'units')::numeric;END IF;
  IF x->>'carryingAmount' IS NOT NULL THEN IF jsonb_typeof(x->'carryingAmount')<>'string' OR x->>'carryingAmount' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' OR(x->>'carryingAmount')::numeric<=0 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;requested_carrying:=(x->>'carryingAmount')::numeric;END IF;
  IF d.kind='INVESTMENT_DISPOSAL' THEN
   IF h."unitMode"='UNIT' THEN
    IF requested_carrying IS NOT NULL OR(all_units AND requested_units IS NOT NULL) OR(NOT all_units AND requested_units IS NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
    unit_basis:=CASE WHEN all_units THEN units_remaining ELSE requested_units END;
    IF unit_basis<=0 OR unit_basis>units_remaining THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
    cost_basis:=CASE WHEN unit_basis=units_remaining THEN cost_remaining ELSE round(cost_remaining*unit_basis/units_remaining,2) END;
    carrying_basis:=CASE WHEN unit_basis=units_remaining THEN carrying_remaining ELSE round(carrying_remaining*unit_basis/units_remaining,2) END;
   ELSE
    IF requested_units IS NOT NULL OR(all_units AND requested_carrying IS NOT NULL) OR(NOT all_units AND requested_carrying IS NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
    carrying_basis:=CASE WHEN all_units THEN carrying_remaining ELSE requested_carrying END;
    IF carrying_basis<0 OR carrying_basis>carrying_remaining OR(NOT all_units AND carrying_basis<=0) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
    cost_basis:=CASE WHEN carrying_basis=carrying_remaining THEN cost_remaining ELSE round(cost_remaining*carrying_basis/carrying_remaining,2) END;
   END IF;
  ELSE
   IF all_units OR requested_units IS NOT NULL OR requested_carrying IS NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
   carrying_basis:=requested_carrying;
   IF d.kind<>'INVESTMENT_VALUATION_UP' AND carrying_basis>carrying_remaining THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
  END IF;
  INSERT INTO public."FinanceInvestmentAllocation"(id,"movementId","lotId",sequence,"requestedUnits","requestedCarrying","disposeAll","costBasis","carryingBasis","unitBasis","basisCapturedAt","balanceDigest") VALUES(gen_random_uuid(),target,l.id,n,requested_units,requested_carrying,all_units,cost_basis,carrying_basis,unit_basis,captured,public.encova_finance_investment_lot_digest(l.id,captured));
 END LOOP;
END $$;
CREATE FUNCTION encova_finance_investment_register_only(target UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT coalesce(d.amount=0 AND d."feeAmount"=0 AND((d.kind='INVESTMENT_DISPOSAL' AND EXISTS(SELECT 1 FROM public."FinanceInvestmentAllocation" WHERE "movementId"=d.id) AND NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentAllocation" WHERE "movementId"=d.id AND "carryingBasis"<>0)) OR(d.kind='REVERSAL' AND o.kind='INVESTMENT_DISPOSAL' AND EXISTS(SELECT 1 FROM public."FinanceInvestmentAllocation" WHERE "movementId"=o.id) AND NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentAllocation" WHERE "movementId"=o.id AND "carryingBasis"<>0))),false) FROM public."FinanceMovement" d LEFT JOIN public."FinanceMovement" o ON o.id=d."reversalOfId" WHERE d.id=target $$;
CREATE FUNCTION encova_finance_investment_income_expected(target UUID) RETURNS TABLE("holdingId" UUID,amount NUMERIC) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT d."holdingId",CASE WHEN d.kind='INVESTMENT_INCOME_SETTLEMENT' THEN -d.amount ELSE d.amount END FROM public."FinanceMovement" d WHERE d.id=target AND d.kind IN('INVESTMENT_INCOME_ACCRUAL','INVESTMENT_INCOME_SETTLEMENT')
 UNION ALL SELECT v."holdingId",-v.amount FROM public."FinanceMovement" d JOIN public."FinanceInvestmentIncomeEvent" v ON v."movementId"=d."reversalOfId" WHERE d.id=target AND d.kind='REVERSAL';
$$;
ALTER FUNCTION encova_finance_investment_expected(UUID) RENAME TO encova_finance_investment_expected_f23;
CREATE FUNCTION encova_finance_investment_expected(target UUID) RETURNS TABLE("holdingId" UUID,"lotId" UUID,"costDelta" NUMERIC,"carryingDelta" NUMERIC,"unitsDelta" NUMERIC) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT * FROM public.encova_finance_investment_expected_f23(target)
 UNION ALL SELECT d."holdingId",a."lotId",CASE WHEN d.kind='INVESTMENT_DISPOSAL' THEN -a."costBasis" ELSE 0::numeric END,CASE WHEN d.kind='INVESTMENT_VALUATION_UP' THEN a."carryingBasis" ELSE -a."carryingBasis" END,CASE WHEN d.kind='INVESTMENT_DISPOSAL' THEN -a."unitBasis" END FROM public."FinanceMovement" d JOIN public."FinanceInvestmentAllocation" a ON a."movementId"=d.id WHERE d.id=target AND d.kind IN('INVESTMENT_DISPOSAL','INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN');
$$;
ALTER FUNCTION encova_finance_movement_lines(UUID) RENAME TO encova_finance_movement_lines_f23;
CREATE FUNCTION encova_finance_movement_lines(target UUID) RETURNS TABLE(sequence INTEGER,"accountId" UUID,description TEXT,debit NUMERIC,credit NUMERIC,"projectId" UUID,"partyId" UUID) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT * FROM public.encova_finance_movement_lines_f23(target)
 UNION ALL SELECT legs.sequence,legs.account,d.description,legs.debit,legs.credit,NULL::uuid,h."partyId" FROM public."FinanceMovement" d JOIN public."FinanceInvestmentHolding" h ON h.id=d."holdingId" LEFT JOIN public."FinanceCashAccount" c ON c.id=d."toCashId" CROSS JOIN LATERAL(SELECT coalesce(sum("carryingBasis"),0) AS carrying FROM public."FinanceInvestmentAllocation" WHERE "movementId"=d.id)basis CROSS JOIN LATERAL(VALUES
 (1,c."glAccountId",greatest(d.amount-d."feeAmount",0),greatest(d."feeAmount"-d.amount,0)),
 (2,h."feeAccountId",d."feeAmount",0::numeric),
 (3,h."lossAccountId",greatest(basis.carrying-d.amount,0),0::numeric),
 (4,h."gainAccountId",0::numeric,greatest(d.amount-basis.carrying,0)),
 (5,h."investmentAccountId",0::numeric,basis.carrying))legs(sequence,account,debit,credit) WHERE d.id=target AND d.kind='INVESTMENT_DISPOSAL' AND(legs.debit>0 OR legs.credit>0)
 UNION ALL SELECT legs.sequence,legs.account,d.description,legs.debit,legs.credit,NULL::uuid,h."partyId" FROM public."FinanceMovement" d JOIN public."FinanceInvestmentHolding" h ON h.id=d."holdingId" LEFT JOIN public."FinanceCashAccount" c ON c.id=d."toCashId" CROSS JOIN LATERAL(VALUES
 (1,CASE WHEN d.kind IN('INVESTMENT_INCOME_RECEIPT','INVESTMENT_INCOME_SETTLEMENT') THEN c."glAccountId" WHEN d.kind='INVESTMENT_INCOME_ACCRUAL' THEN h."incomeControlAccountId" WHEN d.kind='INVESTMENT_VALUATION_UP' THEN h."investmentAccountId" WHEN d.kind='INVESTMENT_IMPAIRMENT' THEN h."impairmentAccountId" ELSE h."valuationOffsetAccountId" END,d.amount,0::numeric),
 (2,CASE WHEN d.kind IN('INVESTMENT_INCOME_RECEIPT','INVESTMENT_INCOME_ACCRUAL') THEN h."incomeAccountId" WHEN d.kind='INVESTMENT_INCOME_SETTLEMENT' THEN h."incomeControlAccountId" WHEN d.kind='INVESTMENT_VALUATION_UP' THEN h."valuationOffsetAccountId" ELSE h."investmentAccountId" END,0::numeric,d.amount))legs(sequence,account,debit,credit) WHERE d.id=target AND d.kind IN('INVESTMENT_INCOME_RECEIPT','INVESTMENT_INCOME_ACCRUAL','INVESTMENT_INCOME_SETTLEMENT','INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN');
$$;
ALTER TABLE "FinanceInvestmentAllocation" ADD CHECK("requestedUnits">0),ADD CHECK("requestedCarrying">0),ADD CHECK("unitBasis">=0);
CREATE FUNCTION encova_finance_investment_check_allocation(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE a public."FinanceInvestmentAllocation"%ROWTYPE;d public."FinanceMovement"%ROWTYPE;h public."FinanceInvestmentHolding"%ROWTYPE;c NUMERIC;v NUMERIC;u NUMERIC;ec NUMERIC:=0;ev NUMERIC:=0;eu NUMERIC;BEGIN
 SELECT * INTO a FROM public."FinanceInvestmentAllocation" WHERE id=target;SELECT * INTO d FROM public."FinanceMovement" WHERE id=a."movementId";SELECT * INTO h FROM public."FinanceInvestmentHolding" WHERE id=d."holdingId";
 IF a.id IS NULL OR NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentLot" WHERE id=a."lotId" AND "holdingId"=d."holdingId" AND "acquisitionDate"<=d."postingDate") OR a."balanceDigest" IS DISTINCT FROM public.encova_finance_investment_lot_digest(a."lotId",a."basisCapturedAt") THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 SELECT coalesce(sum("costDelta"),0),coalesce(sum("carryingDelta"),0),coalesce(sum("unitsDelta"),0) INTO c,v,u FROM public."FinanceInvestmentEvent" WHERE "lotId"=a."lotId" AND "effectiveDate"<=d."postingDate" AND "recordedAt"<=a."basisCapturedAt";
 IF d.kind='INVESTMENT_DISPOSAL' THEN
  IF h."unitMode"='UNIT' THEN
   IF a."requestedCarrying" IS NOT NULL OR(a."disposeAll" AND a."requestedUnits" IS NOT NULL) OR(NOT a."disposeAll" AND a."requestedUnits" IS NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
   eu:=CASE WHEN a."disposeAll" THEN u ELSE a."requestedUnits" END;IF eu<=0 OR eu>u THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
   ec:=CASE WHEN eu=u THEN c ELSE round(c*eu/u,2) END;ev:=CASE WHEN eu=u THEN v ELSE round(v*eu/u,2) END;
  ELSE
   IF a."requestedUnits" IS NOT NULL OR(a."disposeAll" AND a."requestedCarrying" IS NOT NULL) OR(NOT a."disposeAll" AND a."requestedCarrying" IS NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
   ev:=CASE WHEN a."disposeAll" THEN v ELSE a."requestedCarrying" END;IF ev<0 OR ev>v OR(NOT a."disposeAll" AND ev<=0) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
   ec:=CASE WHEN ev=v THEN c ELSE round(c*ev/v,2) END;
  END IF;
 ELSE
  IF a."disposeAll" OR a."requestedUnits" IS NOT NULL OR a."requestedCarrying" IS NULL OR(c<=0 AND u<=0) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
  ev:=a."requestedCarrying";IF d.kind<>'INVESTMENT_VALUATION_UP' AND ev>v THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
 END IF;
 IF ROW(a."costBasis",a."carryingBasis",a."unitBasis") IS DISTINCT FROM ROW(ec,ev,eu) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
END $$;
ALTER FUNCTION encova_finance_movement_validate(UUID) RENAME TO encova_finance_movement_validate_f23;
CREATE FUNCTION encova_finance_movement_validate(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;h public."FinanceInvestmentHolding"%ROWTYPE;a public."FinanceInvestmentAllocation"%ROWTYPE;v RECORD;minimum NUMERIC;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=target FOR UPDATE;
 IF d.kind NOT IN('INVESTMENT_DISPOSAL','INVESTMENT_INCOME_RECEIPT','INVESTMENT_INCOME_ACCRUAL','INVESTMENT_INCOME_SETTLEMENT','INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN') THEN PERFORM public.encova_finance_movement_validate_f23(target);ELSE
  SELECT * INTO h FROM public."FinanceInvestmentHolding" WHERE id=d."holdingId" FOR UPDATE;
  IF d.state<>'DRAFT' OR h.id IS NULL OR NOT h.active OR h."policyStatus"<>'REVIEWED' OR d."partyId" IS DISTINCT FROM h."partyId" OR d."fromCashId" IS NOT NULL OR d."controlAccountId" IS NOT NULL OR d."counterAccountId" IS NOT NULL OR d."loanId" IS NOT NULL OR d."billId" IS NOT NULL OR d."projectId" IS NOT NULL OR d.units IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=h."partyId" AND active) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;
  IF NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."investmentAccountId" AND active AND "isPosting" AND "controlType"='INVESTMENT') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."gainAccountId" AND active AND "isPosting" AND "controlType"='NONE' AND type='OTHER_INCOME') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."lossAccountId" AND active AND "isPosting" AND "controlType"='NONE' AND type='OTHER_EXPENSE') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."feeAccountId" AND active AND "isPosting" AND "controlType"='NONE' AND type IN('DIRECT_COST','OPERATING_EXPENSE','OTHER_EXPENSE')) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."incomeAccountId" AND active AND "isPosting" AND "controlType"='NONE' AND type='OTHER_INCOME') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."incomeControlAccountId" AND active AND "isPosting" AND "controlType"='INVESTMENT_INCOME_RECEIVABLE') THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_POLICY' USING ERRCODE='P0001';END IF;
  IF d.kind IN('INVESTMENT_INCOME_RECEIPT','INVESTMENT_INCOME_SETTLEMENT') OR(d.kind='INVESTMENT_DISPOSAL' AND d.amount<>d."feeAmount") THEN
   IF d."toCashId" IS NULL OR NOT EXISTS(SELECT 1 FROM public."FinanceCashAccount" c JOIN public."FinanceAccount" account ON account.id=c."glAccountId" WHERE c.id=d."toCashId" AND c.active AND account.active AND account."controlType"='CASH' AND account."isPosting") THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;
  ELSIF d."toCashId" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF d.kind IN('INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN') THEN
   IF d."approvalEvidence" IS NULL OR length(trim(d."approvalEvidence"))<3 OR(d.kind<>'INVESTMENT_IMPAIRMENT' AND(h."measurementMode"<>'MANUAL_VALUATION' OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."valuationOffsetAccountId" AND active AND "isPosting" AND "controlType"='NONE' AND type=CASE WHEN h."valuationTreatment"='EQUITY' THEN 'EQUITY' ELSE 'OTHER_INCOME' END))) OR(d.kind='INVESTMENT_IMPAIRMENT' AND NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=h."impairmentAccountId" AND active AND "isPosting" AND "controlType"='NONE' AND type='OTHER_EXPENSE')) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_POLICY' USING ERRCODE='P0001';END IF;
   IF d.amount IS DISTINCT FROM(SELECT coalesce(sum("carryingBasis"),0) FROM public."FinanceInvestmentAllocation" WHERE "movementId"=target) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
  END IF;
 END IF;
 FOR a IN SELECT * FROM public."FinanceInvestmentAllocation" WHERE "movementId"=target LOOP
  IF a."balanceDigest" IS DISTINCT FROM public.encova_finance_investment_lot_digest(a."lotId",'infinity'::timestamptz) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_STALE_LOT' USING ERRCODE='P0001';END IF;PERFORM public.encova_finance_investment_check_allocation(a.id);
 END LOOP;
 FOR v IN SELECT * FROM public.encova_finance_investment_income_expected(target) LOOP
  IF v.amount<0 THEN
   SELECT coalesce(min((SELECT coalesce(sum(e.amount),0) FROM public."FinanceInvestmentIncomeEvent" e WHERE e."holdingId"=v."holdingId" AND e."effectiveDate"<=dates.dt)),0) INTO minimum FROM(SELECT d."postingDate" AS dt UNION SELECT "effectiveDate" FROM public."FinanceInvestmentIncomeEvent" WHERE "holdingId"=v."holdingId" AND "effectiveDate">=d."postingDate")dates;
   IF minimum < -v.amount THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_INCOME_CAPACITY' USING ERRCODE='P0001';END IF;
  END IF;
 END LOOP;
END $$;
ALTER FUNCTION encova_finance_movement_effects(UUID,UUID,UUID) RENAME TO encova_finance_movement_effects_f23;
CREATE FUNCTION encova_finance_movement_effects(actor UUID,target UUID,entry_id UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 INSERT INTO public."FinanceInvestmentIncomeEvent"(id,"holdingId","movementId","journalId","effectiveDate",amount) SELECT gen_random_uuid(),v."holdingId",target,entry_id,d."postingDate",v.amount FROM public.encova_finance_investment_income_expected(target)v JOIN public."FinanceMovement" d ON d.id=target;
 UPDATE public."FinanceInvestmentHolding" SET "usedAt"=coalesce("usedAt",CURRENT_TIMESTAMP) WHERE id IN(SELECT "holdingId" FROM public.encova_finance_investment_income_expected(target));
 PERFORM public.encova_finance_movement_effects_f23(actor,target,entry_id);
END $$;
ALTER FUNCTION encova_finance_check_movement(UUID) RENAME TO encova_finance_check_movement_f23;
CREATE FUNCTION encova_finance_check_movement(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;j UUID;a public."FinanceInvestmentAllocation"%ROWTYPE;BEGIN
 IF target IS NULL THEN RETURN;END IF;PERFORM public.encova_finance_check_movement_f23(target);SELECT * INTO d FROM public."FinanceMovement" WHERE id=target;SELECT id INTO j FROM public."FinanceJournalEntry" WHERE "movementId"=target;
 IF(d.kind IN('INVESTMENT_DISPOSAL','INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN'))<>(EXISTS(SELECT 1 FROM public."FinanceInvestmentAllocation" WHERE "movementId"=target)) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 FOR a IN SELECT * FROM public."FinanceInvestmentAllocation" WHERE "movementId"=target LOOP PERFORM public.encova_finance_investment_check_allocation(a.id);END LOOP;
 IF d.state<>'POSTED' THEN IF EXISTS(SELECT 1 FROM public."FinanceInvestmentIncomeEvent" WHERE "movementId"=target) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;RETURN;END IF;
 IF EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "movementId"=target AND("journalId" IS DISTINCT FROM j OR("journalId" IS NULL AND NOT public.encova_finance_investment_register_only(target)))) OR EXISTS((SELECT "holdingId",amount FROM public."FinanceInvestmentIncomeEvent" WHERE "movementId"=target) EXCEPT(SELECT * FROM public.encova_finance_investment_income_expected(target))) OR EXISTS((SELECT * FROM public.encova_finance_investment_income_expected(target)) EXCEPT(SELECT "holdingId",amount FROM public."FinanceInvestmentIncomeEvent" WHERE "movementId"=target)) OR EXISTS(SELECT 1 FROM public."FinanceInvestmentIncomeEvent" WHERE "movementId"=target AND("journalId" IS DISTINCT FROM j OR "effectiveDate"<>d."postingDate")) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT sum(amount) OVER(PARTITION BY "holdingId" ORDER BY "effectiveDate" RANGE UNBOUNDED PRECEDING) balance FROM public."FinanceInvestmentIncomeEvent" WHERE "holdingId" IN(SELECT "holdingId" FROM public.encova_finance_investment_income_expected(target)))v WHERE balance<0) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_INCOME_CAPACITY' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT l.cost AS original_cost,l.units AS original_units,sum(e."costDelta") OVER(PARTITION BY e."lotId" ORDER BY e."effectiveDate" RANGE UNBOUNDED PRECEDING) cost,sum(e."unitsDelta") OVER(PARTITION BY e."lotId" ORDER BY e."effectiveDate" RANGE UNBOUNDED PRECEDING) units FROM public."FinanceInvestmentEvent" e JOIN public."FinanceInvestmentLot" l ON l.id=e."lotId" WHERE e."lotId" IN(SELECT "lotId" FROM public.encova_finance_investment_expected(target)))v WHERE cost>original_cost OR units>original_units) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
END $$;
CREATE FUNCTION encova_finance_investment_allocation_check() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN PERFORM public.encova_finance_check_movement(CASE WHEN TG_OP='DELETE' THEN OLD."movementId" ELSE NEW."movementId" END);RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER "FinanceInvestmentAllocation_valid" AFTER INSERT OR DELETE ON "FinanceInvestmentAllocation" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_investment_allocation_check();
CREATE CONSTRAINT TRIGGER "FinanceInvestmentIncomeEvent_valid" AFTER INSERT ON "FinanceInvestmentIncomeEvent" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_investment_event_check();
DO $$ DECLARE def TEXT;BEGIN SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceMovement"'::regclass AND conname='FinanceMovement_kind_check';ALTER TABLE public."FinanceMovement" DROP CONSTRAINT "FinanceMovement_kind_check";EXECUTE 'ALTER TABLE public."FinanceMovement" ADD CONSTRAINT "FinanceMovement_kind_check" CHECK(('||substr(def,8,length(def)-8)||') OR kind IN(''INVESTMENT_DISPOSAL'',''INVESTMENT_INCOME_RECEIPT'',''INVESTMENT_INCOME_ACCRUAL'',''INVESTMENT_INCOME_SETTLEMENT'',''INVESTMENT_IMPAIRMENT'',''INVESTMENT_VALUATION_UP'',''INVESTMENT_VALUATION_DOWN''))';SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceMovement"'::regclass AND conname='FinanceMovement_source_shape';ALTER TABLE public."FinanceMovement" DROP CONSTRAINT "FinanceMovement_source_shape";EXECUTE 'ALTER TABLE public."FinanceMovement" ADD CONSTRAINT "FinanceMovement_source_shape" CHECK(('||substr(def,8,length(def)-8)||') OR(kind IN(''INVESTMENT_DISPOSAL'',''INVESTMENT_INCOME_RECEIPT'',''INVESTMENT_INCOME_ACCRUAL'',''INVESTMENT_INCOME_SETTLEMENT'',''INVESTMENT_IMPAIRMENT'',''INVESTMENT_VALUATION_UP'',''INVESTMENT_VALUATION_DOWN'') AND "holdingId" IS NOT NULL AND "partyId" IS NOT NULL AND "controlAccountId" IS NULL AND "counterAccountId" IS NULL AND "loanId" IS NULL AND "billId" IS NULL AND "projectId" IS NULL AND units IS NULL AND "fromCashId" IS NULL AND "reversalOfId" IS NULL))';END $$;
CREATE FUNCTION encova_finance_movement_digest(input JSONB) RETURNS TEXT LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT encode(sha256(convert_to((jsonb_strip_nulls(input)-CASE WHEN coalesce(input->>'feeAmount','0')::numeric=0 THEN 'feeAmount' ELSE '__absent' END-CASE WHEN coalesce(input->'allocations','[]'::jsonb)='[]'::jsonb THEN 'allocations' ELSE '__absent' END)::text,'UTF8')),'hex') $$;
CREATE OR REPLACE FUNCTION encova_finance_movement_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE d public."FinanceMovement"%ROWTYPE;o public."FinanceMovement"%ROWTYPE;r public."FinanceLedgerReceipt"%ROWTYPE;reason TEXT;digest TEXT;operation_name TEXT;result JSONB;entry_id UUID;original_id UUID;original_version INTEGER;original_number TEXT;BEGIN
 IF action IS NULL OR action NOT IN('CREATE','UPDATE','POST','VOID','REVERSE') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 reason:=trim(input->>'reason');IF reason IS NULL OR length(reason) NOT BETWEEN 3 AND 500 OR input-(CASE WHEN action='CREATE' THEN ARRAY['kind','reference','documentDate','postingDate','description','evidence','approvalEvidence','currency','amount','fromCashId','toCashId','partyId','controlAccountId','counterAccountId','projectId','billId','loanId','holdingId','units','feeAmount','allocations','reason'] WHEN action='UPDATE' THEN ARRAY['id','expectedVersion','kind','reference','documentDate','postingDate','description','evidence','approvalEvidence','currency','amount','fromCashId','toCashId','partyId','controlAccountId','counterAccountId','projectId','billId','loanId','holdingId','units','feeAmount','allocations','reason'] WHEN action='REVERSE' THEN ARRAY['id','expectedVersion','postingDate','reason'] ELSE ARRAY['id','expectedVersion','reason'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 operation_name:='MOVEMENT_'||action;digest:=public.encova_finance_movement_digest(input);SELECT * INTO r FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation=operation_name AND key=request_key;
 IF FOUND THEN IF r."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN r.result;END IF;
 PERFORM pg_advisory_xact_lock(629815);
 IF action<>'CREATE' THEN
  IF jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' OR(input->>'expectedVersion')::integer<1 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO d FROM public."FinanceMovement" WHERE id=(input->>'id')::uuid FOR UPDATE;
  IF d.id IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
  IF d.version<>(input->>'expectedVersion')::integer THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF(action='REVERSE' AND d.state<>'POSTED') OR(action<>'REVERSE' AND d.state<>'DRAFT') THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_IMMUTABLE' USING ERRCODE='P0001';END IF;
 END IF;
 IF action IN('CREATE','UPDATE') THEN
  IF input->>'kind' IS NULL OR input->>'kind' NOT IN('TRANSFER','CAPITAL_CONTRIBUTION','CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT','FOUNDER_REIMBURSEMENT','LOAN_DISBURSEMENT','LOAN_REPAYMENT','LOAN_INTEREST_ACCRUAL','LOAN_INTEREST_SETTLEMENT','LOAN_PRINCIPAL_INCREASE','LOAN_PRINCIPAL_DECREASE','INVESTMENT_ACQUISITION','INVESTMENT_DISPOSAL','INVESTMENT_INCOME_RECEIPT','INVESTMENT_INCOME_ACCRUAL','INVESTMENT_INCOME_SETTLEMENT','INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN') OR input->>'currency' IS DISTINCT FROM 'PKR' OR jsonb_typeof(input->'amount') IS DISTINCT FROM 'string' OR input->>'amount' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' OR(input->>'amount')::numeric<0 OR((input->>'amount')::numeric=0 AND input->>'kind'<>'INVESTMENT_DISPOSAL') OR input->>'documentDate' IS NULL OR input->>'documentDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'postingDate' IS NULL OR input->>'postingDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF input->>'feeAmount' IS NOT NULL AND(jsonb_typeof(input->'feeAmount')<>'string' OR input->>'feeAmount' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$') THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF input->>'kind' LIKE 'INVESTMENT_%'  THEN input:=input||jsonb_build_object('partyId',(SELECT "partyId" FROM public."FinanceInvestmentHolding" WHERE id=(input->>'holdingId')::uuid));IF input->>'units' IS NOT NULL AND(jsonb_typeof(input->'units')<>'string' OR input->>'units' !~ '^(0|[1-9][0-9]{0,13})([.][0-9]{1,6})?$' OR(input->>'units')::numeric<=0) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;END IF;
  IF input->>'kind' LIKE 'LOAN_%'  THEN input:=input||jsonb_build_object('partyId',(SELECT "partyId" FROM public."FinanceLoan" WHERE id=(input->>'loanId')::uuid));END IF;
  IF input->>'kind'='TRANSFER'  AND(input->>'partyId' IS NOT NULL OR input->>'controlAccountId' IS NOT NULL OR input->>'counterAccountId' IS NOT NULL OR input->>'projectId' IS NOT NULL OR input->>'approvalEvidence' IS NOT NULL OR input->>'billId' IS NOT NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF action='CREATE' THEN INSERT INTO public."FinanceMovement"(id,number,kind,reference,"documentDate","postingDate",description,evidence,"approvalEvidence",currency,amount,"fromCashId","toCashId","partyId","controlAccountId","counterAccountId","projectId","billId","loanId","holdingId",units,"feeAmount","createdById") VALUES(gen_random_uuid(),'MVT-'||lpad(nextval('public.finance_movement_number')::text,10,'0'),input->>'kind',input->>'reference',(input->>'documentDate')::date,(input->>'postingDate')::date,input->>'description',input->>'evidence',input->>'approvalEvidence','PKR',(input->>'amount')::numeric,(input->>'fromCashId')::uuid,(input->>'toCashId')::uuid,(input->>'partyId')::uuid,(input->>'controlAccountId')::uuid,(input->>'counterAccountId')::uuid,(input->>'projectId')::uuid,(input->>'billId')::uuid,(input->>'loanId')::uuid,(input->>'holdingId')::uuid,(input->>'units')::numeric,coalesce((input->>'feeAmount')::numeric,0),actor) RETURNING * INTO d;
  ELSE IF input->>'kind' IS DISTINCT FROM d.kind THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;UPDATE public."FinanceMovement" SET "feeAmount"=coalesce((input->>'feeAmount')::numeric,0),"holdingId"=(input->>'holdingId')::uuid,units=(input->>'units')::numeric,"loanId"=(input->>'loanId')::uuid,"partyId"=(input->>'partyId')::uuid,"controlAccountId"=(input->>'controlAccountId')::uuid,"counterAccountId"=(input->>'counterAccountId')::uuid,"projectId"=(input->>'projectId')::uuid,"billId"=(input->>'billId')::uuid,"approvalEvidence"=input->>'approvalEvidence',reference=input->>'reference',"documentDate"=(input->>'documentDate')::date,"postingDate"=(input->>'postingDate')::date,description=input->>'description',evidence=input->>'evidence',amount=(input->>'amount')::numeric,"fromCashId"=(input->>'fromCashId')::uuid,"toCashId"=(input->>'toCashId')::uuid,"updatedAt"=CURRENT_TIMESTAMP,version=version+1 WHERE id=d.id RETURNING * INTO d;END IF;
  PERFORM public.encova_finance_investment_set_allocations(d.id,coalesce(input->'allocations','[]'::jsonb));
 ELSIF action='VOID' THEN UPDATE public."FinanceMovement" SET state='VOIDED',version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=d.id RETURNING * INTO d;
 ELSIF action='REVERSE' THEN
  IF d.kind='REVERSAL' OR input->>'postingDate' IS NULL OR input->>'postingDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR EXISTS(SELECT 1 FROM public."FinanceMovement" WHERE "reversalOfId"=d.id) THEN RAISE EXCEPTION 'FINANCE_REVERSAL_INVALID' USING ERRCODE='P0001';END IF;
  o:=d;original_id:=d.id;original_number:=d.number;original_version:=d.version;
  INSERT INTO public."FinanceMovement" SELECT x.* FROM jsonb_populate_record(NULL::public."FinanceMovement",to_jsonb(o)||jsonb_build_object('id',gen_random_uuid(),'number','MVT-'||lpad(nextval('public.finance_movement_number')::text,10,'0'),'kind','REVERSAL','reversalOfId',o.id,'documentDate',(input->>'postingDate')::date,'postingDate',(input->>'postingDate')::date,'state','DRAFT','version',1,'sourceSnapshot',NULL,'createdById',actor,'createdAt',CURRENT_TIMESTAMP,'updatedAt',CURRENT_TIMESTAMP,'evidence',reason)) x RETURNING * INTO d;
  entry_id:=public.encova_finance_emit_journal(actor,'MOVEMENT',d.id,d."postingDate",reason);SELECT * INTO d FROM public."FinanceMovement" WHERE id=d.id;
 ELSE entry_id:=public.encova_finance_emit_journal(actor,'MOVEMENT',d.id,d."postingDate",reason);SELECT * INTO d FROM public."FinanceMovement" WHERE id=d.id;END IF;
 result:=CASE WHEN action='REVERSE' THEN jsonb_build_object('id',original_id,'version',original_version,'number',original_number,'journalId',entry_id,'reversalId',d.id) ELSE jsonb_build_object('id',d.id,'version',d.version,'number',d.number,'journalId',entry_id) END;
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,operation_name,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_'||operation_name,'FinanceMovement',coalesce(original_id,d.id),reason,jsonb_build_object('journalId',entry_id,'snapshot',to_jsonb(d)||jsonb_build_object('amount',d.amount::text)),request_id);RETURN result;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';
 WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';
END $$;
CREATE OR REPLACE FUNCTION encova_finance_movement_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='DELETE' OR(TG_OP='UPDATE' AND OLD.state<>'DRAFT') THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_IMMUTABLE' USING ERRCODE='P0001';END IF;
 IF TG_OP='INSERT' THEN IF NEW.state<>'DRAFT' OR NEW.version<>1 OR NEW."sourceSnapshot" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;RETURN NEW;END IF;
 IF ROW(NEW.id,NEW.number,NEW.kind,NEW."createdById",NEW."createdAt",NEW."reversalOfId") IS DISTINCT FROM ROW(OLD.id,OLD.number,OLD.kind,OLD."createdById",OLD."createdAt",OLD."reversalOfId") OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
 IF NEW.state<>'DRAFT' AND(to_jsonb(NEW)-ARRAY['state','version','sourceSnapshot','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','version','sourceSnapshot','updatedAt']) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF NEW.state='POSTED' THEN IF NEW."sourceSnapshot" IS DISTINCT FROM public.encova_finance_movement_snapshot(NEW.id) OR(NOT EXISTS(SELECT 1 FROM public."FinanceJournalEntry" WHERE "movementId"=NEW.id) AND NOT public.encova_finance_investment_register_only(NEW.id)) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;ELSIF NEW."sourceSnapshot" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION encova_finance_check_movement_f20(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;e public."FinanceJournalEntry"%ROWTYPE;o public."FinanceMovement"%ROWTYPE;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=target;SELECT * INTO e FROM public."FinanceJournalEntry" WHERE "movementId"=target;
 IF d.state<>'POSTED' THEN IF e.id IS NOT NULL OR d."sourceSnapshot" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;RETURN;END IF;
 IF d.id IS NULL OR(e.id IS NULL AND NOT public.encova_finance_investment_register_only(target)) OR e."sourceType"<>'MOVEMENT' OR e."postingDate"<>d."postingDate" OR e.description<>d.description OR e.evidence<>d.evidence OR d."sourceSnapshot" IS NULL OR EXISTS((SELECT sequence,"accountId",description,debit,credit,"projectId","partyId" FROM public."FinanceJournalLine" WHERE "journalId"=e.id) EXCEPT(SELECT * FROM public.encova_finance_movement_lines(target))) OR EXISTS((SELECT * FROM public.encova_finance_movement_lines(target)) EXCEPT(SELECT sequence,"accountId",description,debit,credit,"projectId","partyId" FROM public."FinanceJournalLine" WHERE "journalId"=e.id)) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF d.kind='REVERSAL' THEN SELECT * INTO o FROM public."FinanceMovement" WHERE id=d."reversalOfId";IF o.state IS DISTINCT FROM 'POSTED' OR o.kind='REVERSAL' OR d."postingDate"<o."postingDate" OR(to_jsonb(d)-ARRAY['id','number','kind','reversalOfId','documentDate','postingDate','state','version','sourceSnapshot','createdById','createdAt','updatedAt','evidence']) IS DISTINCT FROM(to_jsonb(o)-ARRAY['id','number','kind','reversalOfId','documentDate','postingDate','state','version','sourceSnapshot','createdById','createdAt','updatedAt','evidence']) THEN RAISE EXCEPTION 'FINANCE_REVERSAL_INVALID' USING ERRCODE='P0001';END IF;END IF;
END $$;
CREATE OR REPLACE FUNCTION encova_finance_emit_journal(actor UUID,source_kind TEXT,source_id UUID,posting_date DATE,reason TEXT) RETURNS UUID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE movement public."FinanceMovement"%ROWTYPE; supplier public."FinanceSupplierDocument"%ROWTYPE; bill public."FinanceBill"%ROWTYPE; draft public."FinanceJournalDraft"%ROWTYPE; original public."FinanceJournalEntry"%ROWTYPE; invoice public."FinanceInvoice"%ROWTYPE;
 period_id UUID; entry_id UUID:=gen_random_uuid(); mappings UUID[]; customer public."FinanceCustomerDocument"%ROWTYPE;
BEGIN
 IF source_kind IS NULL OR source_kind NOT IN ('JOURNAL_DRAFT','JOURNAL_REVERSAL','INVOICE','CUSTOMER_DOCUMENT','BILL','SUPPLIER_DOCUMENT','MOVEMENT') THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(629815);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 IF source_kind='MOVEMENT' THEN
  SELECT * INTO movement FROM public."FinanceMovement" WHERE id=source_id FOR UPDATE;
  IF movement.id IS NULL OR movement."postingDate"<>posting_date THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
  PERFORM public.encova_finance_movement_validate(source_id);
 ELSIF source_kind='SUPPLIER_DOCUMENT' THEN
  SELECT * INTO supplier FROM public."FinanceSupplierDocument" WHERE id=source_id FOR UPDATE;
  IF supplier.id IS NULL OR supplier."postingDate"<>posting_date THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
  PERFORM public.encova_finance_supplier_validate(source_id);
 ELSIF source_kind='BILL' THEN
  SELECT * INTO bill FROM public."FinanceBill" WHERE id=source_id FOR UPDATE;
  IF bill.id IS NULL OR bill."postingDate"<>posting_date THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
  PERFORM public.encova_finance_bill_validate(source_id);PERFORM public.encova_finance_bill_tax_validate(source_id);
 ELSIF source_kind='INVOICE' THEN
  SELECT * INTO invoice FROM public."FinanceInvoice" WHERE id=source_id FOR UPDATE;
  IF invoice.id IS NULL OR invoice.state<>'DRAFT' OR invoice."postingDate"<>posting_date THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
  PERFORM public.encova_finance_invoice_tax_validate(source_id);
  IF invoice."totalAmount"<=0 THEN RAISE EXCEPTION 'FINANCE_INVOICE_EMPTY' USING ERRCODE='P0001';END IF;
  IF NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=invoice."partyId" AND active AND kind IN ('CLIENT','BOTH')) THEN RAISE EXCEPTION 'FINANCE_INVOICE_PARTY' USING ERRCODE='P0001';END IF;
  IF NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=invoice."receivableAccountId" AND active AND "isPosting" AND NOT "isContra" AND currency='PKR' AND "controlType"='RECEIVABLES' AND type='ASSET') OR EXISTS(
   SELECT 1 FROM public."FinanceInvoiceLine" l JOIN public."FinanceAccount" a ON a.id=l."revenueAccountId" WHERE l."invoiceId"=source_id AND (NOT a.active OR NOT a."isPosting" OR a."isContra" OR a.currency<>'PKR' OR a.type NOT IN ('INCOME','OTHER_INCOME') OR a."controlType"<>'NONE')) OR EXISTS(
   SELECT 1 FROM public."FinanceInvoiceLine" l JOIN public."FinanceAccount" a ON a.id=l."deferredAccountId" WHERE l."invoiceId"=source_id AND l.recognition='DEFERRED' AND (NOT a.active OR NOT a."isPosting" OR a."isContra" OR a.currency<>'PKR' OR a.type<>'LIABILITY' OR a."controlType"<>'DEFERRED_REVENUE')) THEN RAISE EXCEPTION 'FINANCE_INVOICE_MAPPING' USING ERRCODE='P0001';END IF;
  IF (invoice."projectId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."Project" WHERE id=invoice."projectId" AND "archivedAt" IS NULL)) OR EXISTS(SELECT 1 FROM public."FinanceInvoiceLine" l JOIN public."Project" p ON p.id=l."projectId" WHERE l."invoiceId"=source_id AND p."archivedAt" IS NOT NULL) THEN RAISE EXCEPTION 'FINANCE_PROJECT_UNAVAILABLE' USING ERRCODE='P0001';END IF;
 ELSIF source_kind='CUSTOMER_DOCUMENT' THEN
  SELECT * INTO customer FROM public."FinanceCustomerDocument" WHERE id=source_id FOR UPDATE;
  IF customer.id IS NULL OR customer."postingDate"<>posting_date THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
  PERFORM public.encova_finance_customer_validate(source_id);
 ELSE
  SELECT * INTO draft FROM public."FinanceJournalDraft" WHERE id=source_id FOR UPDATE;
  IF draft.id IS NULL OR (source_kind='JOURNAL_DRAFT' AND (draft.state<>'DRAFT' OR draft."postingDate"<>posting_date)) OR (source_kind='JOURNAL_REVERSAL' AND draft.state<>'POSTED') THEN RAISE EXCEPTION 'FINANCE_DRAFT_IMMUTABLE' USING ERRCODE='P0001';END IF;
  IF source_kind='JOURNAL_REVERSAL' THEN
   SELECT * INTO original FROM public."FinanceJournalEntry" WHERE "draftId"=source_id AND "sourceType"='JOURNAL_DRAFT' FOR UPDATE;
   IF original.id IS NULL OR EXISTS(SELECT 1 FROM public."FinanceJournalEntry" WHERE "reversalOfId"=original.id) OR posting_date<original."postingDate" THEN RAISE EXCEPTION 'FINANCE_REVERSAL_INVALID' USING ERRCODE='P0001';END IF;
  END IF;
 END IF;
 SELECT id INTO period_id FROM public."FinancePeriod" WHERE state='OPEN' AND posting_date BETWEEN "startDate" AND "endDate" FOR UPDATE;
 IF period_id IS NULL THEN RAISE EXCEPTION 'FINANCE_PERIOD_UNAVAILABLE' USING ERRCODE='P0001';END IF;
 IF posting_date>(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Karachi')::date THEN RAISE EXCEPTION 'FINANCE_FUTURE_DATE' USING ERRCODE='P0001';END IF;
 IF source_kind='JOURNAL_DRAFT' THEN
  INSERT INTO public."FinanceJournalEntry"(id,reference,"sourceType","sourceId","sourceAction","draftId","postingDate","periodId",description,evidence,"postedById") VALUES(entry_id,'JRN-'||entry_id::text,'JOURNAL_DRAFT',draft.id,'POST',draft.id,posting_date,period_id,draft.description,draft.evidence,actor);
  INSERT INTO public."FinanceJournalLine"(id,"journalId",sequence,"accountId",description,debit,credit,"projectId") SELECT gen_random_uuid(),entry_id,sequence,"accountId",description,debit,credit,"projectId" FROM public."FinanceJournalDraftLine" WHERE "draftId"=draft.id ORDER BY "accountId",sequence;
  UPDATE public."FinanceJournalDraft" SET state='POSTED',version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=draft.id;
 ELSIF source_kind='JOURNAL_REVERSAL' THEN
  INSERT INTO public."FinanceJournalEntry"(id,reference,"sourceType","sourceId","sourceAction","postingDate","periodId",description,evidence,"postedById","reversalOfId") VALUES(entry_id,'JRN-'||entry_id::text,'JOURNAL_REVERSAL',original.id,'REVERSE',posting_date,period_id,original.description,reason,actor,original.id);
  INSERT INTO public."FinanceJournalLine"(id,"journalId",sequence,"accountId",description,debit,credit,"projectId") SELECT gen_random_uuid(),entry_id,sequence,"accountId",description,credit,debit,"projectId" FROM public."FinanceJournalLine" WHERE "journalId"=original.id ORDER BY "accountId",sequence;
 ELSIF source_kind='MOVEMENT' THEN
  IF public.encova_finance_investment_register_only(movement.id) THEN entry_id:=NULL;UPDATE public."FinancePeriod" SET "usedAt"=coalesce("usedAt",CURRENT_TIMESTAMP) WHERE id=period_id;ELSE
  INSERT INTO public."FinanceJournalEntry"(id,reference,"sourceType","sourceId","sourceAction","movementId","postingDate","periodId",description,evidence,"postedById") VALUES(entry_id,'JRN-'||entry_id::text,'MOVEMENT',movement.id,'POST',movement.id,posting_date,period_id,movement.description,movement.evidence,actor);
  INSERT INTO public."FinanceJournalLine"(id,"journalId",sequence,"accountId",description,debit,credit,"projectId","partyId") SELECT gen_random_uuid(),entry_id,x.* FROM public.encova_finance_movement_lines(movement.id) x ORDER BY x."accountId",x.sequence;
  END IF;
  PERFORM public.encova_finance_movement_effects(actor,movement.id,entry_id);
 ELSIF source_kind='SUPPLIER_DOCUMENT' THEN
  INSERT INTO public."FinanceJournalEntry"(id,reference,"sourceType","sourceId","sourceAction","supplierDocumentId","postingDate","periodId",description,evidence,"postedById") VALUES(entry_id,'JRN-'||entry_id::text,'SUPPLIER_DOCUMENT',supplier.id,'POST',supplier.id,posting_date,period_id,supplier.description,supplier.evidence,actor);
  INSERT INTO public."FinanceJournalLine"(id,"journalId",sequence,"accountId",description,debit,credit,"projectId","partyId","billLineId") SELECT gen_random_uuid(),entry_id,x.* FROM public.encova_finance_supplier_lines(supplier.id) x ORDER BY x."accountId",x.sequence;
  PERFORM public.encova_finance_supplier_effects(actor,supplier.id,entry_id);
 ELSIF source_kind='SUPPLIER_DOCUMENT' THEN
  INSERT INTO public."FinanceJournalEntry"(id,reference,"sourceType","sourceId","sourceAction","supplierDocumentId","postingDate","periodId",description,evidence,"postedById") VALUES(entry_id,'JRN-'||entry_id::text,'SUPPLIER_DOCUMENT',supplier.id,'POST',supplier.id,posting_date,period_id,supplier.description,supplier.evidence,actor);
  INSERT INTO public."FinanceJournalLine"(id,"journalId",sequence,"accountId",description,debit,credit,"projectId","partyId","billLineId") SELECT gen_random_uuid(),entry_id,x.* FROM public.encova_finance_supplier_lines(supplier.id) x ORDER BY x."accountId",x.sequence;
  PERFORM public.encova_finance_supplier_effects(actor,supplier.id,entry_id);
 ELSIF source_kind='BILL' THEN
  INSERT INTO public."FinanceJournalEntry"(id,reference,"sourceType","sourceId","sourceAction","billId","postingDate","periodId",description,evidence,"postedById") VALUES(entry_id,'JRN-'||entry_id::text,'BILL',bill.id,'POST',bill.id,posting_date,period_id,bill.description,bill.evidence,actor);
  INSERT INTO public."FinanceJournalLine"(id,"journalId",sequence,"accountId",description,debit,credit,"projectId","partyId","billLineId") SELECT gen_random_uuid(),entry_id,x.* FROM public.encova_finance_bill_lines(bill.id) x ORDER BY x."accountId",x.sequence;
  PERFORM public.encova_finance_bill_effects(bill.id,entry_id);
 ELSIF source_kind='CUSTOMER_DOCUMENT' THEN
  INSERT INTO public."FinanceJournalEntry"(id,reference,"sourceType","sourceId","sourceAction","customerDocumentId","postingDate","periodId",description,evidence,"postedById") VALUES(entry_id,'JRN-'||entry_id::text,'CUSTOMER_DOCUMENT',customer.id,'POST',customer.id,posting_date,period_id,customer.description,customer.evidence,actor);
  INSERT INTO public."FinanceJournalLine"(id,"journalId",sequence,"accountId",description,debit,credit,"projectId","partyId","invoiceLineId") SELECT gen_random_uuid(),entry_id,x.* FROM public.encova_finance_customer_lines(customer.id) x ORDER BY x."accountId",x.sequence;
  PERFORM public.encova_finance_customer_effects(actor,customer.id,entry_id);
 ELSE
  INSERT INTO public."FinanceJournalEntry"(id,reference,"sourceType","sourceId","sourceAction","invoiceId","postingDate","periodId",description,evidence,"postedById") VALUES(entry_id,'JRN-'||entry_id::text,'INVOICE',invoice.id,'POST',invoice.id,posting_date,period_id,invoice.description,invoice.evidence,actor);
  INSERT INTO public."FinanceJournalLine"(id,"journalId",sequence,"accountId",description,debit,credit,"projectId","partyId","invoiceLineId") SELECT gen_random_uuid(),entry_id,x.* FROM public.encova_finance_invoice_lines(invoice.id) x ORDER BY x."accountId",x.sequence;
  INSERT INTO public."FinanceReceivableEvent"(id,"invoiceId","partyId","accountId","journalId","effectiveDate",kind,amount) VALUES(gen_random_uuid(),invoice.id,invoice."partyId",invoice."receivableAccountId",entry_id,posting_date,'INVOICE',invoice."totalAmount");
  INSERT INTO public."FinanceDeferredRevenueEvent"(id,"invoiceLineId","journalId","effectiveDate",kind,amount) SELECT gen_random_uuid(),id,entry_id,posting_date,'BILLED',"netAmount" FROM public."FinanceInvoiceLine" WHERE "invoiceId"=invoice.id AND recognition='DEFERRED' AND "netAmount">0;
  SELECT array_agg(id) INTO mappings FROM public."FinanceAccount" WHERE id=invoice."receivableAccountId" OR id IN(SELECT "revenueAccountId" FROM public."FinanceInvoiceLine" WHERE "invoiceId"=invoice.id) OR id IN(SELECT "deferredAccountId" FROM public."FinanceInvoiceLine" WHERE "invoiceId"=invoice.id);
  PERFORM public.encova_finance_mark_accounts(mappings);
  UPDATE public."FinanceParty" SET "usedAt"=coalesce("usedAt",CURRENT_TIMESTAMP) WHERE id=invoice."partyId";
  UPDATE public."FinanceInvoice" SET state='POSTED',version=version+1,"partySnapshot"=public.encova_finance_party_snapshot("partyId"),"updatedAt"=CURRENT_TIMESTAMP WHERE id=invoice.id;
 END IF;
 RETURN entry_id;
END $$;
CREATE OR REPLACE FUNCTION encova_finance_holding_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'FINANCE_HISTORY_IMMUTABLE' USING ERRCODE='P0001';END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.number,NEW."createdById",NEW."createdAt") IS DISTINCT FROM ROW(OLD.id,OLD.number,OLD."createdById",OLD."createdAt") OR(NEW.version<>OLD.version+1 AND(to_jsonb(NEW)-ARRAY['usedAt','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['usedAt','updatedAt'])) THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF OLD."usedAt" IS NOT NULL AND(to_jsonb(NEW)-ARRAY['name','active','version','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['name','active','version','updatedAt']) THEN RAISE EXCEPTION 'FINANCE_HOLDING_TERMS_USED' USING ERRCODE='P0001';END IF;
  IF NEW."usedAt" IS DISTINCT FROM OLD."usedAt" AND(OLD."usedAt" IS NOT NULL OR(NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "holdingId"=NEW.id) AND NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentIncomeEvent" WHERE "holdingId"=NEW.id))) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 END IF;
 IF NOT NEW.active AND EXISTS(SELECT 1 FROM public."FinanceInvestmentIncomeEvent" WHERE "holdingId"=NEW.id HAVING coalesce(sum(amount),0)<>0) THEN RAISE EXCEPTION 'FINANCE_HOLDING_OUTSTANDING' USING ERRCODE='P0001';END IF;
 IF NOT NEW.active AND EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "holdingId"=NEW.id HAVING coalesce(sum("costDelta"),0)<>0 OR coalesce(sum("carryingDelta"),0)<>0 OR coalesce(sum("unitsDelta"),0)<>0) THEN RAISE EXCEPTION 'FINANCE_HOLDING_OUTSTANDING' USING ERRCODE='P0001';END IF;
 IF TG_OP='INSERT' OR OLD."usedAt" IS NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=NEW."partyId" AND active) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."investmentAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='INVESTMENT' AND "reportGroup"=CASE WHEN NEW.classification='CURRENT' THEN 'CURRENT_ASSETS' ELSE 'NONCURRENT_ASSETS' END) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;
  IF NEW."policyStatus"='REVIEWED' AND(NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."gainAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_INCOME') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."lossAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_EXPENSE') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."feeAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type IN('DIRECT_COST','OPERATING_EXPENSE','OTHER_EXPENSE')) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."incomeAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_INCOME') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."incomeControlAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='INVESTMENT_INCOME_RECEIVABLE') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."impairmentAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_EXPENSE') OR(NEW."measurementMode"='MANUAL_VALUATION' AND NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."valuationOffsetAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type=CASE WHEN NEW."valuationTreatment"='EQUITY' THEN 'EQUITY' ELSE 'OTHER_INCOME' END))) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_POLICY' USING ERRCODE='P0001';END IF;
 END IF;RETURN NEW;END $$;
ALTER FUNCTION encova_finance_movement_snapshot(UUID) RENAME TO encova_finance_movement_snapshot_f23;
CREATE FUNCTION encova_finance_movement_snapshot(target UUID) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT public.encova_finance_movement_snapshot_f23(target)||CASE WHEN d.kind LIKE 'INVESTMENT_%' AND d.kind<>'INVESTMENT_ACQUISITION' THEN jsonb_build_object('holding',to_jsonb(h),'feeAmount',d."feeAmount"::text,'allocations',(SELECT coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('costBasis',a."costBasis"::text,'carryingBasis',a."carryingBasis"::text,'unitBasis',a."unitBasis"::text) ORDER BY a.sequence),'[]'::jsonb) FROM public."FinanceInvestmentAllocation" a WHERE a."movementId"=d.id)) ELSE '{}'::jsonb END FROM public."FinanceMovement" d LEFT JOIN public."FinanceInvestmentHolding" h ON h.id=d."holdingId" WHERE d.id=target $$;
DO $$ DECLARE item RECORD;role_name TEXT;t TEXT;BEGIN
 FOREACH t IN ARRAY ARRAY['FinanceInvestmentAllocation','FinanceInvestmentIncomeEvent'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC',t);IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN EXECUTE format('GRANT SELECT ON public.%I TO encova_app',t);EXECUTE format('CREATE POLICY encova_server_read ON public.%I FOR SELECT TO encova_app USING(true)',t);END IF;FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON public.%I FROM %I',t,role_name);END IF;END LOOP;END LOOP;
 FOR item IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND(proname LIKE 'encova_finance_investment_%' OR proname LIKE 'encova_finance_movement_%' OR proname LIKE 'encova_finance_check_movement%') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',item.signature);FOREACH role_name IN ARRAY ARRAY['anon','authenticated','encova_app'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',item.signature,role_name);END IF;END LOOP;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION encova_finance_movement_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID) TO encova_app;END IF;
END $$;
COMMIT;
